import Foundation

extension MeetingSessionStoreCheckpointTests {
    /// Uses the real session, reading resolver and encoder. The only fixture in Git is
    /// synthetic text generated by this exact export method for the web importer.
    static func checkProtectedPortableExport(check: (Bool, String) -> Void) async throws {
        func id(_ suffix: String) -> UUID { UUID(uuidString: "00000000-0000-4000-8000-" + suffix)! }
        let timebase = MeetingTimebaseMetadata(startedHostTime: 0, machTimebaseNumerator: 1,
            machTimebaseDenominator: 1, firstPresentationTime: nil)
        var session = MeetingSession(id: id("000000000001"), configuration: .init(mode: .inRoom,
            title: "Обсуждение синтетического проекта", languageCode: "ru",
            microphone: .init(captureDeviceID: "/private/never-export-device", displayName: "Private microphone")),
            startedAt: Date(timeIntervalSince1970: 1_700_000_000), timebase: timebase)
        session.state = .completed
        session.endedAt = session.startedAt.addingTimeInterval(5)
        session.audioStorageMode = .memoryOnly
        session.piiRedactionEnabled = true
        // Keep the established portable-import fixture's anonymous legacy turn.
        // Default/enabled complete ownership is covered by the reading contract.
        session.speakerLabelsEnabled = false
        session.transcriptTimeDomain = .meetingRelative
        let trackID = id("000000000010"), ownerID = id("000000000002"), remoteID = id("000000000003")
        let aliasID = id("000000000004")
        let owner = MeetingSessionSpeaker(id: ownerID, displayName: "Борис Ёлкин", diarizationClusterID: "private-owner-cluster",
            diarizationEmbedding: [0.123, 0.456], trackKind: .microphone, isLocalUser: true, identityCandidates: [])
        let remote = MeetingSessionSpeaker(id: remoteID, displayName: "Алёна Ёжик", diarizationClusterID: "private-remote-cluster",
            trackKind: .microphone, isLocalUser: false, identityCandidates: [])
        var alias = remote
        alias.id = aliasID; alias.displayName = "Retired private alias"; alias.mergedIntoSpeakerID = remoteID
        session.speakers = [owner, remote, alias]
        session.recordingBackendID = "private-model-evidence"
        session.audioTracks = [.init(id: trackID, kind: .microphone, sourceIdentifier: "/private/never-export-audio.caf",
            sourceDisplayName: "Private microphone", format: nil, timebase: timebase, health: .waiting, chunks: [])]
        let epoch = MeetingAnalysisEpochID(trackID: trackID, ordinal: 0)
        let ownerToken = MeetingBackendSpeakerToken(analysisEpochID: epoch, label: "private-owner-token")
        let remoteToken = MeetingBackendSpeakerToken(analysisEpochID: epoch, label: "private-remote-token")
        func segment(_ number: Int, _ start: Int64, _ end: Int64, _ text: String,
                     speakerID: UUID?, rule: MeetingSpeakerAttributionRule = .rawAssigned) -> MeetingTranscriptSegment {
            var value = MeetingTranscriptSegment(id: id(String(format: "%012d", number)),
                start: .init(value: start, timescale: 10), end: .init(value: end, timescale: 10),
                sourceTrackID: trackID, speakerID: speakerID, text: text, revision: 0, status: .final,
                overlap: .none, completeness: .complete, attributionState: speakerID == nil ? .timingUncertain : .assigned)
            value.nativePrecision = .word; value.nativeUnitID = "private-native-unit-\(number)"
            value.nativeTiming = .init(start: Double(start) / 10, end: Double(end) / 10)
            if let speakerID {
                let token = speakerID == ownerID ? ownerToken : remoteToken
                let decision = MeetingSpeakerAttributionDecision(unitID: value.nativeUnitID!, rawAssignment: .assigned(token),
                    candidates: [], activeSupportSeconds: 0.2, simultaneousIntervals: [],
                    relation: rule == .briefInterruption ? .simultaneous : .single, selectedToken: token,
                    rule: rule, cueUnitIDs: [], backgroundTokens: rule == .briefInterruption ? [remoteToken] : [],
                    policyVersion: 2, policyFingerprint: "private-attribution-policy")
                value.nativeSpeakerAssignment = .assigned(token)
                value.speakerAttribution = .init(decision: decision, speakerIDs: [ownerToken: ownerID, remoteToken: remoteID])
            }
            return value
        }
        session.transcriptSegments = [
            segment(101, 0, 2, "Привет,", speakerID: ownerID),
            segment(102, 2, 4, "обсудим", speakerID: ownerID, rule: .neighborAgreement),
            segment(103, 4, 8, "проект.", speakerID: ownerID, rule: .briefInterruption),
            segment(104, 10, 13, "Всё", speakerID: remoteID),
            segment(105, 13, 16, "готово.", speakerID: aliasID),
            segment(106, 20, 30, "Контакт: [PERSON].", speakerID: nil)
        ]
        let original = session
        let fullJSON = try MeetingTranscriptExporter.json(for: session)
        let fullText = MeetingTranscriptExporter.text(for: session)
        let exported = try MeetingTranscriptExporter.protectedTranscriptJSON(for: session)
        let object = try JSONSerialization.jsonObject(with: exported) as! [String: Any]
        check(Set(object.keys) == ["format", "schemaVersion", "sessionID", "title", "languageCode", "startedAt", "endedAt",
                                   "durationSeconds", "speakers", "segments", "privacy"], "Portable top-level fields are an explicit allowlist")
        check(object["format"] as? String == "pichi-voice-transcript" && object["schemaVersion"] as? Int == 1,
              "Portable identifier and schema match the import contract")
        check(object["sessionID"] as? String == session.id.uuidString, "Session identity remains stable across exports")
        let privacy = object["privacy"] as! [String: Bool]
        check(privacy == ["transcriptPIIRedacted": true, "includesAudio": false, "metadataMayContainPersonalData": true],
              "Privacy declaration distinguishes protected speech, audio and user metadata")
        let speakers = object["speakers"] as! [[String: Any]]
        check(speakers.count == 2 && speakers[0]["displayName"] as? String == owner.displayName
              && speakers[1]["displayName"] as? String == remote.displayName,
              "Cyrillic user aliases remain metadata, including the local user's saved name")
        let paragraphs = readableParagraphs(session)
        let presentations = MeetingTranscriptExporter.speakerPresentations(in: session)
        let rows = object["segments"] as! [[String: Any]]
        check(rows.count == paragraphs.count && rows.count == 3, "Native word fragments become final readable turns")
        for (row, paragraph) in zip(rows, paragraphs) {
            check(Set(row.keys).isSubset(of: ["id", "startSeconds", "endSeconds", "speakerID", "text"]),
                  "Grouped turns cannot claim native word precision or leak canonical evidence")
            check(row["id"] as? String == paragraph.id.uuidString && row["text"] as? String == paragraph.text,
                  "Turn identity is its first member and text exactly matches the UI projection")
            check(row["startSeconds"] as? Double == paragraph.segments.map { $0.start.seconds }.min()
                  && row["endSeconds"] as? Double == paragraph.segments.map { $0.end.seconds }.max(),
                  "Exported intervals use real member bounds")
            check(row["speakerID"] as? String == presentations[paragraph.id]?.participantID?.uuidString,
                  "Neighbor, interruption, alias and unknown owners agree with the UI")
        }
        check(rows[0]["speakerID"] as? String == ownerID.uuidString && rows[1]["speakerID"] as? String == remoteID.uuidString
              && rows[2]["speakerID"] == nil, "Only resolved active speaker IDs appear in portable turns")
        let roundtrip = try JSONSerialization.jsonObject(with: JSONSerialization.data(withJSONObject: object)) as! NSDictionary
        check(roundtrip == object as NSDictionary, "Portable JSON survives a consumer parse/encode roundtrip")
        let repeatedFullJSON = try MeetingTranscriptExporter.json(for: session)
        check(session == original && repeatedFullJSON == fullJSON
              && MeetingTranscriptExporter.text(for: session) == fullText, "Portable export cannot mutate canonical JSON, text or stored evidence")
        let string = String(decoding: exported, as: UTF8.self)
        check(!string.contains("private-") && !string.contains("/private/") && !string.contains("Retired private alias"),
              "Audio/device paths, biometric and model/attribution evidence remain private")

        let fixtureURL = URL(fileURLWithPath: "Tests/Fixtures/protected-transcript-v1.json")
        if CommandLine.arguments.dropFirst(2).contains("--write-public-fixture") {
            try FileManager.default.createDirectory(at: fixtureURL.deletingLastPathComponent(), withIntermediateDirectories: true)
            try exported.write(to: fixtureURL, options: .atomic)
        }
        check(try Data(contentsOf: fixtureURL) == exported, "Committed public fixture is generated by the actual Swift export")
        let shared = try await MeetingTranscriptExporter.protectedTranscriptJSONForSharing(for: session)
        check(shared == exported, "The off-actor sharing operation preserves the pure portable contract")
        let cancelled = Task { try await MeetingTranscriptExporter.protectedTranscriptJSONForSharing(for: session) }
        cancelled.cancel()
        do { _ = try await cancelled.value; check(false, "Cancelled handoff must not return share data") }
        catch is CancellationError { check(true, "Cancelled handoff joins without publishing share data") }

        func rejects(_ value: MeetingSession, _ expected: MeetingTranscriptExporter.PortableExportError,
                     _ message: String) throws {
            do { _ = try MeetingTranscriptExporter.protectedTranscriptJSON(for: value); check(false, message) }
            catch let error as MeetingTranscriptExporter.PortableExportError {
                check(String(describing: error) == String(describing: expected), message)
            }
        }
        var invalid = session; invalid.piiRedactionEnabled = false
        try rejects(invalid, .protectedTranscriptRequired, "PII-off recordings cannot claim protected speech")
        invalid.piiRedactionEnabled = nil
        try rejects(invalid, .protectedTranscriptRequired, "Old unprotected archives cannot claim protected speech")
        var located = session
        located.defaultTitleBase = "In-room meeting"
        located.location = .init(latitude: 37, longitude: -122, horizontalAccuracy: 10,
            capturedAt: located.startedAt, addresses: [PichiLocalization.language.rawValue: "10 Example Street, Sample City"])
        let locatedObject = try JSONSerialization.jsonObject(with:
            MeetingTranscriptExporter.protectedTranscriptJSON(for: located)) as! [String: Any]
        check(locatedObject["title"] as? String == located.displayTitle
              && (locatedObject["title"] as? String)?.contains("Example Street") == false,
              "The export uses the canonical title without turning separate place metadata into its name")
        located.location?.addresses[PichiLocalization.language.rawValue] = String(repeating: "я", count: 201)
        let separatePlaceObject = try JSONSerialization.jsonObject(with:
            MeetingTranscriptExporter.protectedTranscriptJSON(for: located)) as! [String: Any]
        check(separatePlaceObject["title"] as? String == located.displayTitle,
              "Unexported place metadata does not become an unrelated title-size rejection")
        located.defaultTitleBase = nil
        located.title = String(repeating: "я", count: 201)
        try rejects(located, .limitExceeded, "The actual exported custom title retains its existing size limit")
        invalid = session; invalid.state = .recording
        try rejects(invalid, .protectedTranscriptRequired, "A live recording cannot be handed off as completed")
        invalid = session; invalid.transcriptSegments[0].originalText = "PRIVATE ORIGINAL"
        try rejects(invalid, .protectedTranscriptRequired, "Retained raw originals block protected handoff")
        invalid = session; invalid.transcriptSegments[0].end = .init(value: -1, timescale: 10)
        try rejects(invalid, .invalidTranscript, "Invalid timing cannot be silently repaired or fabricated")
        invalid = session; invalid.transcriptSegments[0].status = .provisional
        try rejects(invalid, .invalidTranscript, "Partial text cannot appear as a final readable turn")
        invalid = session; invalid.transcriptSegments[0].start.timescale = 0
        try rejects(invalid, .invalidTranscript, "A missing media timescale cannot fabricate a zero start")
        invalid = session; invalid.transcriptSegments[1].id = invalid.transcriptSegments[0].id
        try rejects(invalid, .invalidTranscript, "Duplicate unit IDs cannot collapse projection identities")
        invalid = session; invalid.endedAt = invalid.startedAt.addingTimeInterval(-1)
        try rejects(invalid, .invalidTranscript, "Negative duration is rejected")
        invalid = session; invalid.startedAt = Date(timeIntervalSince1970: .infinity)
        try rejects(invalid, .invalidTranscript, "Nonfinite dates and duration are rejected")
        invalid = session; invalid.title = String(repeating: "😀", count: 101)
        try rejects(invalid, .limitExceeded, "Metadata limits count UTF-16 units like the web importer")
        invalid = session; invalid.languageCode = String(repeating: "x", count: 36)
        try rejects(invalid, .limitExceeded, "Language code cap is enforced")
        invalid = session; invalid.speakers[0].displayName = String(repeating: "я", count: 201)
        try rejects(invalid, .limitExceeded, "Participant metadata cap is enforced")
        invalid = session; invalid.transcriptSegments = [session.transcriptSegments[0]]
        invalid.transcriptSegments[0].text = String(repeating: "я", count: 100_000)
        check(try MeetingTranscriptExporter.protectedTranscriptJSON(for: invalid).count <= 750_000,
              "The documented transcript character boundary remains usable")
        invalid.transcriptSegments[0].text.append("я")
        try rejects(invalid, .limitExceeded, "Oversized transcript text is rejected before projection")
        invalid.transcriptSegments = Array(session.transcriptSegments.prefix(2))
        invalid.transcriptSegments[0].text = String(repeating: "a", count: 50_000)
        invalid.transcriptSegments[1].text = String(repeating: "b", count: 50_000)
        try rejects(invalid, .limitExceeded, "Inserted readable separators count toward the final text cap")
        invalid = session; invalid.transcriptSegments = (0...10_000).map { index in
            var row = session.transcriptSegments[0]
            row.id = UUID(); row.sourceTrackID = UUID()
            row.start = .init(value: Int64(index), timescale: 1); row.end = row.start
            row.text = "x"
            return row
        }
        try rejects(invalid, .limitExceeded, "The portable segment cap applies to exported readable turns")
        invalid = session; invalid.transcriptSegments = []
        invalid.speakers = (0..<4_000).map { _ in
            var speaker = remote; speaker.id = UUID(); speaker.displayName = String(repeating: "я", count: 200)
            return speaker
        }
        try rejects(invalid, .limitExceeded, "Final UTF-8 byte cap includes participant metadata and JSON overhead")
    }

    private static func readableParagraphs(_ session: MeetingSession) -> [MeetingTranscriptExporter.DisplayParagraph] {
        let segments = session.transcriptSegments.enumerated().filter { !$0.element.isEcho }.sorted {
            ($0.element.start, $0.element.end, $0.offset) < ($1.element.start, $1.element.end, $1.offset)
        }.map(\.element)
        return MeetingTranscriptExporter.displayParagraphs(for: segments, in: session)
    }
}
